CREATE OR REPLACE FUNCTION public.icash_finish_dealmachine_request(p_request uuid, p_result jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare k text;v jsonb;clean jsonb;
begin
 if coalesce(p_result->>'outcome','') not in ('response','http_error','unknown') or jsonb_typeof(p_result) is distinct from 'object' then return false;end if;
 clean:=jsonb_build_object('outcome',p_result->>'outcome');
 foreach k in array array['httpStatus','returned','creditsUsed','minuteRemaining','dayRemaining','retryAfter','minuteLimit','minuteReset','dayLimit'] loop
  v:=p_result->k;
  if v is not null and v<>'null'::jsonb then
   if jsonb_typeof(v)<>'number' or v::text !~ '^[0-9]{1,10}$' then return false;end if;
   clean:=clean||jsonb_build_object(k,v);
  end if;
 end loop;
 update icash_research_private.requests set finished_at=now(),result=clean where id=p_request and admitted and finished_at is null;

 if not found then return false;end if;
 -- The response belongs to a durable admitted request. Retain its original
 -- observation even if another response arrived sooner; latest metadata uses
 -- request start order, and an older 429 can only extend an existing hold.
 update icash_research_private.quota_feedback f set
  request_id=case when f.request_started_at is null or r.created_at>=f.request_started_at then r.id else f.request_id end,
  request_started_at=greatest(f.request_started_at,r.created_at),observed_at=now(),
  headers=case when f.request_started_at is null or r.created_at>=f.request_started_at then clean else f.headers end,
  blocked_until=greatest(f.blocked_until,
   case when clean->>'httpStatus'='429' then now()+make_interval(secs=>least(86400,greatest(1,coalesce((clean->>'retryAfter')::bigint,60)))::integer)
    when clean->>'minuteRemaining'='0' and (clean->>'minuteReset')::bigint between extract(epoch from now()) and extract(epoch from now()+interval '2 minutes') then to_timestamp((clean->>'minuteReset')::bigint)
   end)
 from icash_research_private.requests r where f.id=1 and r.id=p_request and r.admitted;
 return true;

end $function$

CREATE OR REPLACE FUNCTION public.icash_record_owner_export_receipt(p_account uuid, p_batch uuid, p_receipt jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e icash_research_private.owner_exports;r jsonb:=p_receipt->'raw';terminal boolean;
begin
 perform pg_advisory_xact_lock(hashtextextended('dealmachine:organization:owner-export',0));
 select x.* into e from icash_research_private.owner_exports x join icash_research_private.owner_batches b on b.id=x.id where x.id=p_batch and b.account_id=p_account for update of x;
 if not found or jsonb_typeof(p_receipt) is distinct from 'object' or octet_length(p_receipt::text)>1100000 or jsonb_typeof(p_receipt->'httpStatus') is distinct from 'number' or (p_receipt->>'httpStatus')::integer not between 100 and 599 or jsonb_typeof(p_receipt->'rawText') is distinct from 'string' then return false;end if;
 if e.receipt is not null then return e.receipt=p_receipt;end if;
 if r is distinct from 'null'::jsonb and (p_receipt->>'rawText')::jsonb is distinct from r then return false;end if;
 if r is distinct from 'null'::jsonb and not public.icash_record_owner_batch_receipt(p_account,p_batch,r) then return false;end if;
 terminal:=p_receipt->'httpStatus'='200'::jsonb and coalesce(r->>'export_id','') ~ '^[-a-zA-Z0-9_]{1,128}$' and jsonb_typeof(r->'record_count')='number' and coalesce(r->>'record_count','') ~ '^[0-9]{1,3}$' and r->'file_count'='1'::jsonb;
 update icash_research_private.owner_exports set receipt=p_receipt,terminal_at=case when terminal then clock_timestamp() else null end where id=p_batch;
 return true;
end $function$

CREATE OR REPLACE FUNCTION icash_research_private.guard_capacity_precision_followup()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p icash_research_private.owner_export_capacity_reviews;incident timestamptz;latest timestamptz;data jsonb;x jsonb;
begin

 if tg_op='UPDATE' and row(old.auto_policy,old.auto_attempt) is distinct from row(new.auto_policy,new.auto_attempt) then raise exception 'Automatic capacity policy is immutable';end if;
 if new.auto_policy in ('idle-v1','gateway-idle-v1','empty-idle-v1','unknown-idle-v1') then
  if tg_op='UPDATE' then
   if old.supersedes is distinct from new.supersedes then raise exception 'Capacity review parent is immutable';end if;
   return new;
  end if;
  if new.state<>'planned' or new.request_id is not null or new.receipt is not null or new.started_at is not null or new.checked_at is not null then raise exception 'Fresh automatic capacity claim required';end if;
  if new.supersedes is null then
   if new.auto_attempt<>1 then raise exception 'First automatic capacity attempt required';end if;
  else
   select * into p from icash_research_private.owner_export_capacity_reviews where id=new.supersedes;
   if p.id is null or p.auto_policy is distinct from new.auto_policy or p.state not in ('checking','held')
    or row(p.export_id,p.receipt_hash) is distinct from row(new.export_id,new.receipt_hash)
    or new.auto_attempt<>p.auto_attempt+1
    or new.created_at<coalesce(p.started_at,p.created_at)+make_interval(secs=>least(3600,120*power(2,least(p.auto_attempt-1,5))::integer)) then raise exception 'Automatic capacity backoff required';end if;
  end if;
  return new;
 end if;
 if tg_op='UPDATE' then
  if old.supersedes is distinct from new.supersedes then raise exception 'Capacity review parent is immutable';end if;
  return new;
 end if;
 if new.supersedes is null then return new;end if;
 select * into p from icash_research_private.owner_export_capacity_reviews where id=new.supersedes;
 select b.created_at into incident from icash_research_private.owner_batches b where b.id=new.export_id;
 if p.id is null or p.supersedes is not null or p.state<>'held'
  or row(p.export_id,p.receipt_hash) is distinct from row(new.export_id,new.receipt_hash)
  or new.state<>'planned' or new.request_id is not null or new.started_at is not null or new.checked_at is not null or new.receipt is not null
  or p.receipt->'httpStatus' is distinct from '200'::jsonb or (p.receipt->>'rawText')::jsonb is distinct from p.receipt->'raw'
  or p.started_at is null or p.checked_at is null or p.checked_at-p.started_at not between interval '0 seconds' and interval '30 seconds'
  or incident is null then raise exception 'Held precision review required';end if;
 data:=p.receipt#>'{raw,data}';
 if jsonb_typeof(data) is distinct from 'array' or jsonb_array_length(data) not between 1 and 100
  or (p.receipt#>'{raw,pagination}' @> '{"limit":100,"offset":0,"has_more":false}'::jsonb) is distinct from true
  or p.receipt#>'{raw,pagination,total}' is distinct from to_jsonb(jsonb_array_length(data))
  or (select count(distinct v->>'export_id') from jsonb_array_elements(data) v)<>jsonb_array_length(data)
  or coalesce(p.receipt#>>'{headers,minuteRemaining}','') !~ '^[0-9]{1,10}$' or (p.receipt#>>'{headers,minuteRemaining}')::bigint<=0
  or coalesce(p.receipt#>>'{headers,dayRemaining}','') !~ '^[0-9]{1,10}$' or (p.receipt#>>'{headers,dayRemaining}')::bigint<=0 then raise exception 'Complete idle precision evidence required';end if;
 for x in select value from jsonb_array_elements(data) loop
  if coalesce(x->>'export_id','') !~ '^[-a-zA-Z0-9_]{1,128}$' or coalesce(x->>'status','') not in ('failed','completed')
   or (x->>'created_at')::timestamptz is null or (x->>'created_at')::timestamptz>p.checked_at+interval '5 seconds' then raise exception 'Complete idle precision evidence required';end if;
  latest:=greatest(latest,(x->>'created_at')::timestamptz);
 end loop;
 if latest is distinct from date_trunc('second',incident) or latest>=incident then raise exception 'Same-second precision mismatch required';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_automatic_export_capacity(p_release text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e icash_research_private.owner_exports;r icash_research_private.owner_export_capacity_reviews;previous icash_research_private.owner_export_capacity_reviews;request uuid:=gen_random_uuid();source_policy text;beneficiary uuid;candidate record;
begin
 if p_release is null or p_release !~ '^[a-f0-9]{40}$' or not exists(select 1 from icash_research_private.export_capacity_automation where id=1 and enabled)
  or not public.icash_owner_active_export_enabled()
  or not pg_try_advisory_xact_lock(hashtextextended('dealmachine:organization:owner-export',0)) then return null;end if;
 select * into e from icash_research_private.owner_exports where terminal_at is null and capacity_review_id is null for update;
 if not found or icash_research_private.capacity_source_current(e.id,icash_research_private.capacity_source_fingerprint(e.id)) is distinct from true then return null;end if;
 source_policy:=icash_research_private.capacity_source_policy(e.id,icash_research_private.capacity_source_fingerprint(e.id));
 select * into previous from icash_research_private.owner_export_capacity_reviews where export_id=e.id order by created_at desc,id desc limit 1;
 if found then
  -- Explicit manual reviews retain their existing operator authority.
  if previous.auto_policy is distinct from source_policy or previous.receipt_hash<>icash_research_private.capacity_source_fingerprint(e.id) or previous.state not in ('checking','held')
   or coalesce(previous.started_at,previous.created_at)+make_interval(secs=>least(3600,120*power(2,least(previous.auto_attempt-1,5))::integer))>now() then return null;end if;
 end if;

 -- Ordinary capacity remains first. Visit only eligible starters in due order
 -- and stop at the first real dependency; empty accounts cannot hide later work.
 if not public.icash_dealmachine_capacity_available(3) then
  for candidate in select c.account_id from public.icash_discovery_configs c
   where c.enabled and c.auto_enabled and c.contacts_enabled and c.data_rights_until>now()
    and public.icash_new_user_request_reserve_eligible(c.account_id)
    and public.icash_dealmachine_capacity_available(3,c.account_id)
   order by c.next_run_at,c.account_id loop
   if icash_research_private.starter_export_dependency_current(candidate.account_id) then beneficiary:=candidate.account_id;exit;end if;
  end loop;
  if beneficiary is null then return null;end if;
 end if;
 insert into icash_research_private.owner_export_capacity_reviews(export_id,receipt_hash,reviewed_release,auto_policy,auto_attempt,supersedes,source_snapshot)
 values(e.id,icash_research_private.capacity_source_fingerprint(e.id),p_release,source_policy,coalesce(previous.auto_attempt,0)+1,previous.id,case when source_policy='unknown-idle-v1' then icash_research_private.unknown_capacity_source_snapshot(e.id) end) returning * into r;
 if not public.icash_take_dealmachine_request('owner_preview',beneficiary,'export-capacity-auto:'||r.id||':inventory',request) then
  update icash_research_private.owner_export_capacity_reviews set state='held' where id=r.id;return null;
 end if;
 update icash_research_private.owner_export_capacity_reviews set state='checking',request_id=request,started_at=clock_timestamp() where id=r.id;
 insert into icash_research_private.export_capacity_probes(review_id,probe,request_id) values(r.id,'inventory',request);
 return jsonb_build_object('reviewId',r.id,'requestId',request);
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_export_capacity_probe(p_review uuid, p_probe text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r icash_research_private.owner_export_capacity_reviews;request uuid:=gen_random_uuid();beneficiary uuid;
begin
 if p_probe is null or p_probe not in ('pending','processing') or not pg_try_advisory_xact_lock(hashtextextended('dealmachine:organization:owner-export',0)) then return null;end if;
 select * into r from icash_research_private.owner_export_capacity_reviews where id=p_review for update;

 if not found then return null;end if;
 -- The first admitted request is immutable attribution for all later probes.
 select q.account_id into beneficiary from icash_research_private.requests q
  where q.id=r.request_id and q.admitted and q.kind='owner_preview'
   and q.operation_key='export-capacity-auto:'||r.id||':inventory';
 if not found or (beneficiary is not null and not icash_research_private.starter_export_dependency_current(beneficiary)) then return null;end if;
 if coalesce(r.auto_policy,'') not in ('idle-v1','gateway-idle-v1','empty-idle-v1','unknown-idle-v1') or r.state<>'checking' or r.started_at<clock_timestamp()-interval '60 seconds'
  or not exists(select 1 from icash_research_private.export_capacity_automation where id=1 and enabled)
  or icash_research_private.capacity_source_current(r.export_id,r.receipt_hash) is distinct from true
  or exists(select 1 from icash_research_private.export_capacity_probes where review_id=r.id and probe=p_probe)
  or not exists(select 1 from icash_research_private.export_capacity_probes where review_id=r.id and probe='inventory' and receipt->'httpStatus'='200'::jsonb)
  or not public.icash_take_dealmachine_request('owner_preview',beneficiary,'export-capacity-auto:'||r.id||':'||p_probe,request) then return null;end if;
 insert into icash_research_private.export_capacity_probes(review_id,probe,request_id) values(r.id,p_probe,request);
 return request;
end $function$

CREATE OR REPLACE FUNCTION public.icash_finish_automatic_export_capacity(p_review uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r icash_research_private.owner_export_capacity_reviews;p icash_research_private.export_capacity_probes;raw jsonb;x jsonb;receipts jsonb;valid boolean:=true;latest timestamptz;stamp timestamptz;incident timestamptz;n integer;total integer;
begin
 if not pg_try_advisory_xact_lock(hashtextextended('dealmachine:organization:owner-export',0)) then return 'capacity_review_held';end if;
 select * into r from icash_research_private.owner_export_capacity_reviews where id=p_review for update;
 if not found or coalesce(r.auto_policy,'') not in ('idle-v1','gateway-idle-v1','empty-idle-v1','unknown-idle-v1') then return 'capacity_review_held';end if;
 if r.state='verified' then return 'capacity_verified';end if;
 if r.state<>'checking' then return 'capacity_review_held';end if;

 if r.auto_policy='unknown-idle-v1' then
  perform 1 from icash_research_private.owner_exports where id=r.export_id for update;
  perform 1 from icash_research_private.owner_batches where id=r.export_id for update;
  perform 1 from icash_research_private.requests where id=r.export_id for update;
  perform 1 from public.icash_automation_tickets where id=(r.source_snapshot#>>'{handler,id}')::uuid for update;
 end if;
 select jsonb_object_agg(probe,jsonb_build_object('requestId',request_id,'receipt',receipt,'receivedAt',received_at)),count(*) into receipts,n from icash_research_private.export_capacity_probes where review_id=r.id;
 select created_at into incident from icash_research_private.owner_batches where id=r.export_id;
 valid:=n=3 and r.started_at>clock_timestamp()-interval '60 seconds' and incident is not null
  and exists(select 1 from icash_research_private.export_capacity_automation where id=1 and enabled)
  and icash_research_private.capacity_source_current(r.export_id,r.receipt_hash) is true;
 begin
  for p in select * from icash_research_private.export_capacity_probes where review_id=r.id loop
   raw:=p.receipt->'raw';
   if r.auto_policy='unknown-idle-v1' and icash_research_private.capacity_probe_response_fresh(p.receipt,p.started_at,p.received_at) is distinct from true then valid:=false;exit;end if;

   if p.received_at is null or p.received_at-p.started_at not between interval '0 seconds' and interval '30 seconds'
    or p.receipt->'httpStatus' is distinct from '200'::jsonb or (p.receipt->>'rawText')::jsonb is distinct from raw
    or jsonb_typeof(raw->'data') is distinct from 'array' or raw#>'{pagination,limit}' is distinct from '100'::jsonb or raw#>'{pagination,offset}' is distinct from '0'::jsonb
    or coalesce(raw#>>'{pagination,total}','') !~ '^[0-9]{1,9}$'
    or coalesce(p.receipt#>>'{headers,minuteRemaining}','') !~ '^[0-9]{1,10}$' or (p.receipt#>>'{headers,minuteRemaining}')::bigint<=0
    or coalesce(p.receipt#>>'{headers,dayRemaining}','') !~ '^[0-9]{1,10}$' or (p.receipt#>>'{headers,dayRemaining}')::bigint<=0
    or not exists(select 1 from icash_research_private.requests q where q.id=p.request_id and q.admitted and q.kind='owner_preview' and q.account_id is not distinct from (select original.account_id from icash_research_private.requests original where original.id=r.request_id) and q.operation_key='export-capacity-auto:'||r.id||':'||p.probe) then valid:=false;exit;end if;
   n:=jsonb_array_length(raw->'data');total:=(raw#>>'{pagination,total}')::integer;
   if p.probe<>'inventory' then
    if n<>0 or total<>0 or raw#>'{pagination,has_more}' is distinct from 'false'::jsonb then valid:=false;exit;end if;
   else
    if n not between 1 and 100 or n<>least(total,100) or raw#>'{pagination,has_more}' is distinct from to_jsonb(total>n)
     or (select count(distinct v->>'export_id') from jsonb_array_elements(raw->'data') v)<>n then valid:=false;exit;end if;
    for x in select value from jsonb_array_elements(raw->'data') loop
     if coalesce(x->>'export_id','') !~ '^[-a-zA-Z0-9_]{1,128}$' or coalesce(x->>'status','') not in ('failed','completed') then valid:=false;exit;end if;
     stamp:=(x->>'created_at')::timestamptz;
     if stamp is null or stamp>clock_timestamp()+interval '5 seconds' then valid:=false;exit;end if;
     latest:=greatest(latest,stamp);
    end loop;
   end if;
  end loop;
  valid:=valid and (r.auto_policy in ('empty-idle-v1','unknown-idle-v1') or latest>=date_trunc('second',incident));
 exception when others then valid:=false;
 end;
 -- Keep every response. An interrupted attempt remains separate from a later
 -- read, including a late response that arrives after this final decision.
 update icash_research_private.owner_export_capacity_reviews set receipt=jsonb_build_object('policy',r.auto_policy,'probes',coalesce(receipts,'{}')),checked_at=clock_timestamp(),state=case when valid is true then 'verified' else 'held' end where id=r.id;
 if valid is distinct from true then return 'capacity_review_held';end if;
 update icash_research_private.owner_exports set capacity_review_id=r.id where id=r.export_id;
 return 'capacity_verified';
end $function$

CREATE OR REPLACE FUNCTION icash_research_private.take_reserved_request(p_kind text, p_account uuid, p_operation text, p_request uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.icash_dealmachine_request_budget;s jsonb;allowed boolean:=false;protected boolean:=false;maintenance boolean:=false;bound_sync boolean:=false;
 stamp timestamptz;first_funded timestamptz;
begin
 if p_request is not null and (p_kind is null or p_kind not in ('search_estimate','property_search','owner_preview','owner_lookup','exclusion_create','exclusion_sync','geography','buyer_estimate','buyer_search','property_lookup','photo','phone_dnc')
  or length(coalesce(p_operation,''))>200) then return false;end if;
 select * into b from public.icash_dealmachine_request_budget where id=1 for update;
 if not found then return false;end if;
 if p_request is not null and (exists(select 1 from icash_research_private.requests where id=p_request)
  or exists(select 1 from icash_research_private.request_reserve_admissions where request_id=p_request)
  or exists(select 1 from icash_research_private.maintenance_request_admissions where request_id=p_request)) then return false;end if;
 -- Recheck time after waiting on the limiter, so a stale transaction cannot
 -- extend the new account's first 24 hours or the provider's rolling window.
 stamp:=clock_timestamp();
 s:=icash_research_private.request_reserve_state(stamp);
 bound_sync:=p_request is not null and p_account is null and p_kind='exclusion_sync'
  and icash_research_private.maintenance_exclusion_allowed(p_operation,stamp);
 if s is not null and public.icash_dealmachine_provider_available()
  and b.minute_start<=stamp and b.minute_used>=0 and b.minute_limit>0 then
  if b.minute_start<=stamp-interval '1 minute' then b.minute_start:=stamp;b.minute_used:=0;end if;
  if b.day_start<=stamp-interval '24 hours' then b.day_start:=stamp;b.day_used:=0;end if;
  if b.minute_used<b.minute_limit and b.day_used<b.day_limit then
   -- Only a live exact attached-list sync may use the bounded maintenance lane.
   -- Never list creation/recovery, paid work, caller-supplied labels or starter money.
   if bound_sync and (s->>'maintenanceRemaining')::integer>0 then
    allowed:=true;maintenance:=true;
   else
    allowed:=(s->>'ordinaryRemaining')::integer>0;
   end if;
   if not allowed and p_request is not null and p_operation is not null and length(p_operation)>0
    and (p_kind in ('search_estimate','property_search','owner_preview','owner_lookup','geography','property_lookup')
    or (p_kind='exclusion_sync' and icash_research_private.starter_exclusion_request_allowed(p_account,p_operation,stamp)))
    and (s->>'reserveRemaining')::integer>0
    and icash_research_private.starter_request_allowance(p_account,stamp)>0 then
    allowed:=true;protected:=true;
   end if;
  end if;
 end if;
 if p_operation like 'maintenance-exclusion:%' and not coalesce(bound_sync,false) then allowed:=false;end if;
 if p_request is not null then
  insert into icash_research_private.requests(id,kind,account_id,operation_key,admitted,result)
   values(p_request,p_kind,p_account,p_operation,allowed,case when allowed then null else '{"outcome":"quota_wait"}'::jsonb end);
 end if;
 if not allowed then return false;end if;
 if bound_sync then
  insert into icash_research_private.maintenance_request_admissions(request_id,token,list_id,protected,day_start,created_at)
   select p_request,e.token,e.list_id,maintenance,b.day_start,stamp from icash_research_private.exclusions e
    where e.id=1 and p_operation='maintenance-exclusion:'||e.token;
  if not found then raise exception 'Maintenance request binding changed';end if;
 end if;
 if protected then
  select credited_at into first_funded from public.icash_funding_orders
   where account_id=p_account and mode='live' and state='paid' and credited_at is not null order by credited_at limit 1;
  insert into icash_research_private.request_reserve_admissions(request_id,account_id,day_start,first_funded_at,created_at)
   values(p_request,p_account,b.day_start,first_funded,stamp);
 end if;
 update public.icash_dealmachine_request_budget set minute_start=b.minute_start,minute_used=b.minute_used+1,
  day_start=b.day_start,day_used=b.day_used+1 where id=1;
 return true;
end $function$
